INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (1,1,1,'SELECT nombre_medico, especialidad, cod_especialidad, celular, email FROM points WHERE id_medico = :lk_medico','[\"lk_medico\"]','Datos del médico',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (2,1,2,'SELECT\n    p.nombre_completo AS nombre_paciente,p.nro_hclinica,\n    p.cedula_id AS doc_id,\n    CONCAT(\n        TIMESTAMPDIFF(YEAR,  p.fecha_nacimiento, CURDATE()), \' años - \',\n        TIMESTAMPDIFF(MONTH, p.fecha_nacimiento, CURDATE()) MOD 12,            \' meses\'\n    ) AS edad\nFROM paciente p\nWHERE p.nro_hclinica = :lk_paciente','[\"lk_paciente\"]','Datos del paciente',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,'PACIENTE');
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (3,1,3,'SELECT DATE(a.fecha_atencion) AS fecha_atencion FROM atencion a WHERE a.id_atencion = :lk_atencion','[\"lk_atencion\"]','Fecha de atención',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (11,3,1,'SELECT p.nro_hclinica, p.nombre_completo, p.sexo FROM paciente p WHERE p.nro_hclinica = :lk_paciente','[\"lk_paciente\"]','Datos del paciente',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (12,3,2,'SELECT a.id_atencion AS nro_hoja, a.motivo_consulta, a.revision_sistemas, a.subjetivo, a.objetivo, a.analisis, a.plan, DATE(a.fecha_atencion) AS fecha_atencion,m.nombre_medico AS nombre_medico FROM atencion a,points m WHERE a.lk_medico=m.id_medico AND a.id_atencion = :lk_atencion','[\"lk_atencion\"]','Datos de la atención SOAP',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (13,3,3,'SELECT MAX(CASE WHEN lsv.codigo=\'PESO\' THEN sv.valor END) AS peso, MAX(CASE WHEN lsv.codigo=\'TALLA\' THEN sv.valor END) AS talla, MAX(CASE WHEN lsv.codigo=\'FC\' THEN sv.valor END) AS fc, MAX(CASE WHEN lsv.codigo=\'FR\' THEN sv.valor END) AS fr, MAX(CASE WHEN lsv.codigo=\'TAS\' THEN sv.valor END) AS tas, MAX(CASE WHEN lsv.codigo=\'TAD\' THEN sv.valor END) AS tad, MAX(CASE WHEN lsv.codigo=\'SAT\' THEN sv.valor END) AS saturacion, MAX(CASE WHEN lsv.codigo=\'TEMP\' THEN sv.valor END) AS temp FROM signosvitales sv JOIN lista_signosvitales lsv ON lsv.id_signo_vital=sv.lk_signo_vital WHERE sv.lk_atencion = :lk_atencion','[\"lk_atencion\"]','Signos vitales pivot',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (14,3,4,'SELECT MAX(CASE WHEN n=1 THEN lk_cie10 END) AS cod_cie10_1, MAX(CASE WHEN n=1 THEN nomdiagnostico END) AS que_diagnostico1, MAX(CASE WHEN n=1 THEN tipo END) AS tipo_diagnostico1, MAX(CASE WHEN n=2 THEN lk_cie10 END) AS cod_cie10_2, MAX(CASE WHEN n=2 THEN nomdiagnostico END) AS que_diagnostico2, MAX(CASE WHEN n=2 THEN tipo END) AS tipo_diagnostico2, MAX(CASE WHEN n=3 THEN lk_cie10 END) AS cod_cie10_3, MAX(CASE WHEN n=3 THEN nomdiagnostico END) AS que_diagnostico3, MAX(CASE WHEN n=3 THEN tipo END) AS tipo_diagnostico3, MAX(CASE WHEN n=4 THEN lk_cie10 END) AS cod_cie10_4, MAX(CASE WHEN n=4 THEN nomdiagnostico END) AS que_diagnostico4, MAX(CASE WHEN n=4 THEN tipo END) AS tipo_diagnostico4 FROM (  SELECT d.lk_cie10, c.nomdiagnostico, d.tipo,          ROW_NUMBER() OVER (ORDER BY d.id_diagnostico) AS n   FROM diagnostico d JOIN cie10 c ON c.cod_cie10=d.lk_cie10   JOIN rel_atencion_diagnostico r ON r.lk_diagnostico=d.id_diagnostico   WHERE r.lk_atencion = :lk_atencion AND d.tipo != \'Ant.Personal\') sub','[\"lk_atencion\"]','Diagnósticos pivot 4',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
