INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (27,5,6,'SELECT d.lk_cie10 AS cie, c.nomdiagnostico AS diagnostico, d.tipo AS tipo FROM diagnostico d JOIN cie10 c ON c.cod_cie10=d.lk_cie10 JOIN rel_atencion_diagnostico r ON r.lk_diagnostico=d.id_diagnostico WHERE r.lk_atencion = :lk_atencion AND d.tipo != \'Ant.Personal\' ORDER BY d.id_diagnostico','[\"lk_atencion\"]','Lista diagnósticos',1,'F',1,3,NULL,0,NULL,NULL,1,0,10,NULL);
