INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (31,6,2,'SELECT GROUP_CONCAT(CONCAT(\'[\', IFNULL(d.fecha_inicio_aparente,\'\'), \']: \', c.nomdiagnostico, \' (\', d.lk_cie10, \')\') ORDER BY d.fecha_inicio_aparente DESC SEPARATOR \'\n\') AS ant_personal FROM diagnostico d JOIN cie10 c ON c.cod_cie10=d.lk_cie10 WHERE d.lk_paciente = :lk_paciente AND d.tipo = \'Ant.Personal\'','[\"lk_paciente\"]','Antecedentes personales',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (32,6,4,'SELECT a.sustancia_alergia AS alergia_sust, IFNULL(a.detalles,\'\') AS alergia_coment FROM alergia a WHERE a.lk_paciente = :lk_paciente LIMIT 1','[\"lk_paciente\"]','Primera alergia (posición fija)',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
