INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (34,7,1,'SELECT p.nombre_medico, p.especialidad, p.cod_especialidad, p.celular, p.email FROM points p WHERE p.id_medico = :lk_medico','[\"lk_medico\"]','Datos del médico',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (35,7,2,'SELECT\n    p.nombre_completo AS nombre_paciente,\n    p.cedula_id AS doc_id,\n    CONCAT(\n        TIMESTAMPDIFF(YEAR,  p.fecha_nacimiento, CURDATE()), \' años - \',\n        TIMESTAMPDIFF(MONTH, p.fecha_nacimiento, CURDATE()) MOD 12,            \' meses\'\n    ) AS edad\nFROM paciente p\nWHERE p.nro_hclinica = :lk_paciente','[\"lk_paciente\"]','Datos del paciente',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (36,7,3,'SELECT DATE(NOW()) AS fecha',NULL,'Fecha impresión',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (37,7,4,'SELECT\n    d.lk_cie10 AS cod_cie10,\n    c.nomdiagnostico AS nombre_diagnostico,\n    CONCAT(\'[\', d.lk_cie10, \']: \', c.nomdiagnostico) AS diagnostico\nFROM diagnostico d\nJOIN cie10 c ON c.cod_cie10 = d.lk_cie10\nJOIN rel_atencion_diagnostico r ON r.lk_diagnostico = d.id_diagnostico\nWHERE r.lk_atencion = :lk_atencion\nAND d.tipo != \'Ant.Personal\'\nORDER BY d.id_diagnostico','[\"lk_atencion\"]','Diagnósticos',1,'F',1,10,NULL,0,NULL,NULL,1,0,10,'DIAGNÓSTICO');
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (38,7,5,'SELECT\n    t.examen_tipo AS tipo,\n    c.examen_alias AS alias,\n    c.examen_nombre AS nombre,\n    p.detalle_pedido AS detalle\nFROM examen_pedido p\nJOIN examen_catalogo c ON c.id_examen      = p.lk_catalogo\nJOIN examen_tipo     t ON t.id_examen_tipo = c.lk_examen_tipo\nWHERE p.lk_atencion = :lk_atencion AND (:lk_tipo = 0 OR c.lk_examen_tipo = :lk_tipo)\nORDER BY t.examen_tipo, c.examen_nombre','[\"lk_atencion\", \"lk_tipo\"]','Detalle Pedidos',1,'F',5,6,37,2,NULL,NULL,1,0,10,'PEDIDO');
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (39,7,6,'SELECT p.nombre_medico, p.especialidad, p.cod_especialidad, p.celular, p.email FROM points p WHERE p.id_medico = :lk_medico','[\"lk_medico\"]','Firma Médico',1,'N',1,10,38,7,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (40,4,3,'SELECT DATE(a.fecha_atencion) AS fecha_atencion FROM atencion a WHERE a.id_atencion = :lk_atencion','[\"lk_atencion\"]','Fecha atención',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (41,4,5,'SELECT\n    m.nombre_generico  AS nombre_medicamento,\n    p.concentracion,\n    mp.nombre_presentacion AS presentacion,\n    p.cantidad,\n    p.indicaciones\nFROM prescripcion p\nJOIN medicamentos m  ON p.lk_generico     = m.cod_gen\nJOIN medicamento_presentacion mp ON p.lk_presentacion = mp.id_presentacion\nWHERE p.lk_atencion = :lk_atencion\nORDER BY p.id_prescripcion','[\"lk_atencion\"]','Medicamento',1,'F',4,5,46,1,'SELECT 1 FROM prescripcion WHERE lk_atencion = :lk_atencion LIMIT 1',NULL,1,0,10,'Rp.:');
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (42,4,10,'SELECT m.nombre_generico  AS nombre_medicamento,\n    p.indicaciones\nFROM prescripcion p\nJOIN medicamentos m  ON p.lk_generico     = m.cod_gen\nJOIN medicamento_presentacion mp ON p.lk_presentacion = mp.id_presentacion\nWHERE p.lk_atencion = :lk_atencion\nORDER BY p.id_prescripcion','[\"lk_atencion\"]','Indicaciones',1,'F',4,5,19,2,'SELECT 1 FROM prescripcion WHERE lk_atencion = :lk_atencion LIMIT 1',NULL,1,0,10,'INDICACIONES');
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (46,4,4,'SELECT\n    d.lk_cie10 AS cod_cie10,\n    c.nomdiagnostico AS nombre_diagnostico,\n    CONCAT(\'[\', d.lk_cie10, \']: \', c.nomdiagnostico) AS diagnostico\nFROM diagnostico d\nJOIN cie10 c ON c.cod_cie10 = d.lk_cie10\nJOIN rel_atencion_diagnostico r ON r.lk_diagnostico = d.id_diagnostico\nWHERE r.lk_atencion = :lk_atencion\nAND d.tipo != \'Ant.Personal\'\nORDER BY d.id_diagnostico','[\"lk_atencion\"]','Diagnostico',1,'F',1,4,NULL,0,'SELECT r.id_relacion FROM rel_atencion_diagnostico r WHERE r.lk_atencion=:lk_atencion',NULL,1,0,10,'CIE10:');
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (51,4,6,'SELECT p.nombre_medico, p.especialidad, p.cod_especialidad, p.celular, p.email FROM points p WHERE p.id_medico = :lk_medico','[\"lk_medico\"]','Firma del Médico',1,'N',1,10,41,5,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (52,1,5,'SELECT\n    elg.nombre_grupo,\n    elc.nombre_examen\nFROM examenes_laboratorio_pedido elp\nJOIN examenes_laboratorio_catalogo elc\n    ON elp.lk_examen = elc.id_examen\nJOIN examenes_laboratorio_grupo elg\n    ON elc.lk_grupo = elg.id_grupo\nWHERE elp.lk_atencion = :lk_atencion\nORDER BY elg.nombre_grupo, elc.nombre_examen','[\"lk_atencion\"]','Lista examenes bucle',1,'G',1,10,53,2,'SELECT 1 FROM examenes_laboratorio_pedido\nWHERE lk_atencion = :lk_atencion LIMIT 1','nombre_grupo',3,6,10,'EXAMENES SOLICITADOS');
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (53,1,4,'SELECT\r\n    d.lk_cie10 AS cod_cie10,\r\n    c.nomdiagnostico AS nombre_diagnostico,\r\n    CONCAT(\'[\', d.lk_cie10, \']: \', c.nomdiagnostico) AS diagnostico\r\nFROM diagnostico d\r\nJOIN cie10 c ON c.cod_cie10 = d.lk_cie10\r\nJOIN rel_atencion_diagnostico r ON r.lk_diagnostico = d.id_diagnostico\r\nWHERE r.lk_atencion = :lk_atencion\r\nAND d.tipo != \'Ant.Personal\'\r\nORDER BY d.id_diagnostico','[\"lk_atencion\"]','Diagnosticos Laboratorio',1,'F',1,10,NULL,0,'SELECT 1 FROM prescripcion WHERE lk_atencion = :lk_atencion LIMIT 1',NULL,1,0,10,'CIE10');
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (54,1,6,'SELECT p.nombre_medico, p.especialidad, p.cod_especialidad, p.celular, p.email FROM points p WHERE p.id_medico = :lk_medico','[\"lk_medico\"]','Firma Médico',1,'N',1,10,52,6,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (55,5,7,'SELECT\n  CASE WHEN presenta_sintomas = 1 THEN \'✓ Presenta síntomas\' ELSE \'No presenta síntomas\' END AS chk_sintomas,\n  CASE WHEN aislamiento        = 1 THEN \'✓ Requiere aislamiento\' ELSE \'No requiere aislamiento\' END AS chk_aislamiento\nFROM certificado WHERE lk_atencion = :lk_atencion','[\"lk_atencion\"]','Checks Certificado',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (56,5,8,'SELECT reposo_desde AS desde,reposo_hasta AS hasta FROM certificado WHERE lk_atencion=:lk_atencion','[\"lk_atencion\"]','Fechas de reposo',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (57,5,9,'SELECT lugar_trabajo, ocupacion, observacion FROM certificado WHERE lk_atencion =:lk_atencion','[\"lk_atencion\"]','Observaciones',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
INSERT INTO `reporte_seccion` (`id_seccion`, `lk_impreso`, `orden`, `instruccion_sql`, `parametros_in`, `explica`, `es_activa`, `modo_bucle`, `paso_fila`, `max_iteraciones`, `lk_seccion_ancla`, `ancla_gap`, `condicion_activa_sql`, `campo_grupo`, `num_columnas`, `paso_columna`, `slot_height`, `titulo_seccion`) VALUES (58,5,10,'SELECT p.nombre_medico, p.especialidad, p.cod_especialidad FROM points p WHERE p.id_medico = :lk_medico','[\"lk_medico\"]','Firma Médico',1,'N',1,10,NULL,0,NULL,NULL,1,0,10,NULL);
